class _DropIterator<A> implements Iterator<A> {
  _DropIterator(this._remaining, this._it);
  int _remaining;
  final Iterator<A> _it;
  @override
  late A current;
  @override
  bool moveNext() {
    while (_remaining > 0) {
      _remaining--;
