// ---- lib/src/lazy/effect.dart ----


/// Runs [f], retrying on error until it succeeds or [attempts] runs are
/// exhausted, then rethrows the last error. Between a failure and the next
/// run, waits [delay] (called with the number of failures so far, starting
/// at 1 — return a growing [Duration] for backoff).
///
/// fxdart extension (not part of FxTS), after Rx's `retry`/`retryWhen`.
/// To retry a whole pipeline, wrap its terminal:
/// `retry(3, () => fxAsync(source()).map(parse).toList())`.
///
/// ```dart
/// final user = await retry(3, () => api.fetchUser(id),
///     delay: (failed) => Duration(milliseconds: 100 * failed));
/// ```
Future<T> retry<T>(int attempts, FutureOr<T> Function() f,
    {Duration Function(int failed)? delay}) async {
  _checkAttempts(attempts);
  for (var attempt = 1;; attempt++) {
    try {
      return await f();
    } catch (_) {
      if (attempt >= attempts) rethrow;
      final wait = delay?.call(attempt);
      if (wait != null && wait > Duration.zero) {
        await Future<void>.delayed(wait);
      }
    }
  }
}

void _checkAttempts(int attempts) {
  if (attempts < 1) {
    throw ArgumentError.value(attempts, 'attempts', 'must be at least 1');
  }
}

/// Lazily maps each value with [f], retrying each call up to [attempts]
/// times (see [retry]) before letting the error propagate. Parallel-safe:
/// composes with `concurrent`, and each in-flight value retries
/// independently.
///
/// fxdart extension (not part of FxTS) — the per-element form of [retry].
///
/// ```dart
/// await fxAsync(toAsync(urls))
///     .mapRetry(3, fetch, delay: (failed) => Duration(seconds: failed))
///     .concurrent(5)
///     .toList();
/// ```
@pragma('vm:prefer-inline')
FxAsyncIterable<R> mapRetryAsync<A, R>(
    int attempts, FutureOr<R> Function(A a) f, FxAsyncIterable<A> iterable,
    {Duration Function(int failed)? delay}) {
  _checkAttempts(attempts);
  return mapAsync((A a) => retry(attempts, () => f(a), delay: delay), iterable);
}

/// Fails a pull with a [TimeoutException] when the upstream takes longer
/// than [limit] to produce it. The limit applies to each pull (the time to
/// produce one item), not to inter-item gaps or the whole pipeline.
/// Parallel-safe: overlapping pulls each get their own timer.
///
/// fxdart extension (not part of FxTS), after Rx's `timeout` — but
/// measuring demand-to-item time, the pull-model analog.
///
/// ```dart
/// await fxAsync(toAsync(urls))
///     .map(fetch)
///     .timeout(Duration(seconds: 2))
///     .toList(); // throws TimeoutException if any fetch stalls
/// ```
@pragma('vm:prefer-inline')
FxAsyncIterable<A> timeoutAsync<A>(
    Duration limit, FxAsyncIterable<A> iterable) {
  return DelegateAsyncIterable(
      () => _TimeoutAsyncIterator(limit, iterable.iterator));
}

class _TimeoutAsyncIterator<A> implements FxFastIterator<A> {
  _TimeoutAsyncIterator(this._limit, this._inner);
  final Duration _limit;
  final FxAsyncIterator<A> _inner;

  @override
  Future<IterResult<A>> next([Concurrent? concurrent]) =>
      _inner.next(concurrent).timeout(_limit);

  @override
  FutureOr<IterResult<A>> nextOr() {
    final inner = _inner;
    if (inner is! FxFastIterator<A>) return inner.next().timeout(_limit);
    final r = inner.nextOr();
    // A synchronously answered pull cannot have stalled — no timer needed.
    if (r is Future<IterResult<A>>) return r.timeout(_limit);
    return r;
  }
}

/// Scopes a resource to one lazy iteration: [acquire] runs on the first
/// pull, [use] builds the elements from the resource, and [release] runs
/// exactly once when iteration completes or throws.
///
/// fxdart extension (not part of FxTS), after Rx's `using`.
///
/// **Abandonment caveat:** a consumer that stops pulling mid-iteration
/// (e.g. `break` inside `for-in`) never reaches the end, so [release] does
/// not run. Drive the iterable to completion — bound it with `take` instead
/// of breaking — or manage the resource with `try`/`finally` yourself.
///
/// ```dart
/// final lines = using(
///   () => File('data.txt').openSync(),
///   (file) => readLines(file),
///   (file) => file.closeSync(),
/// );
/// ```
Iterable<T> using<R, T>(R Function() acquire,
        Iterable<T> Function(R resource) use, void Function(R resource) release) =>
    _UsingIterable(acquire, use, release);

class _UsingIterable<R, T> extends Iterable<T> {
  _UsingIterable(this._acquire, this._use, this._release);
  final R Function() _acquire;
  final Iterable<T> Function(R) _use;
  final void Function(R) _release;
  @override
  Iterator<T> get iterator => _UsingIterator(_acquire, _use, _release);
}

class _UsingIterator<R, T> implements Iterator<T> {
  _UsingIterator(this._acquire, this._use, this._release);
  final R Function() _acquire;
  final Iterable<T> Function(R) _use;
  final void Function(R) _release;
  Iterator<T>? _inner;
  late R _resource;
  bool _done = false;
  @override
  T get current => _inner!.current;
  @override
  bool moveNext() {
    if (_done) return false;
    var inner = _inner;
    if (inner == null) {
      // [_acquire] runs on the first pull; a failing acquire has no resource
      // to release (same as the generator form, where acquire sat outside
      // the try/finally).
      _resource = _acquire();
      try {
        inner = _inner = _use(_resource).iterator;
      } catch (_) {
        _done = true;
        _release(_resource);
        rethrow;
      }
    }
    bool moved;
    try {
      moved = inner.moveNext();
    } catch (_) {
      _done = true;
      _release(_resource);
      rethrow;
    }
    if (!moved) {
      _done = true;
      _release(_resource);
    }
    return moved;
  }
}

/// Async counterpart of [using]: [acquire] and [release] may be
/// asynchronous, and the elements come from an [FxAsyncIterable].
/// [release] runs exactly once — after the terminal pull, or before the
/// error propagates when a pull fails (including a failing [use]).
/// The same abandonment caveat as [using] applies.
@pragma('vm:prefer-inline')
FxAsyncIterable<T> usingAsync<R, T>(
    FutureOr<R> Function() acquire,
    FxAsyncIterable<T> Function(R resource) use,
    FutureOr<void> Function(R resource) release) {
  return DelegateAsyncIterable(() => _UsingAsyncIterator(acquire, use, release));
}

/// The [usingAsync] iterator. Public `next` stays a pass-through (as
/// before); the fast-pull path serves synchronously answered inner pulls
/// without futures, releasing exactly once on completion or error.
class _UsingAsyncIterator<R, T> implements FxFastIterator<T> {
  _UsingAsyncIterator(this._acquire, this._use, this._release);
  final FutureOr<R> Function() _acquire;
  final FxAsyncIterable<T> Function(R resource) _use;
  final FutureOr<void> Function(R resource) _release;
  late R _resource;
  var _acquired = false;
  var _done = false;
  FxAsyncIterator<T>? _iterator; // cached once [_started] resolves
  Future<FxAsyncIterator<T>>? _started;
  Future<void>? _releasing;

  Future<void> _releaseOnce() =>
      _releasing ??= Future.sync(() => _release(_resource));

  Future<FxAsyncIterator<T>> _ensureStarted() =>
      _started ??= Future.sync(_acquire).then((r) {
        _resource = r;
        _acquired = true;
        return _iterator = _use(r).iterator;
      });

  Future<IterResult<T>> _settle(Future<IterResult<T>> pull) =>
      pull.then((result) {
        if (!result.done) return result;
        _done = true;
        return _releaseOnce().then((_) => result);
      }, onError: (Object e, StackTrace st) {
        _done = true;
        // When acquire itself failed there is no resource to release.
        if (!_acquired) Error.throwWithStackTrace(e, st);
        return _releaseOnce()
            .then<IterResult<T>>((_) => Error.throwWithStackTrace(e, st));
      });

  @override
  Future<IterResult<T>> next([Concurrent? concurrent]) {
    if (_done) return Future.value(IterResult<T>.done());
    final it = _iterator;
    if (it != null) return _settle(it.next(concurrent));
    return _settle(_ensureStarted().then((i) => i.next(concurrent)));
  }

  @override
  FutureOr<IterResult<T>> nextOr() {
    if (_done) return IterResult<T>.done();
    final it = _iterator;
    if (it == null) {
      return _settle(_ensureStarted().then((i) => i.next()));
    }
    if (it is! FxFastIterator<T>) return _settle(it.next());
    final FutureOr<IterResult<T>> r;
    try {
      r = it.nextOr();
    } catch (e, st) {
      _done = true;
      if (!_acquired) rethrow;
      return _releaseOnce()
          .then<IterResult<T>>((_) => Error.throwWithStackTrace(e, st));
    }
    if (r is Future<IterResult<T>>) return _settle(r);
    if (!r.done) return r;
    _done = true;
    return _releaseOnce().then((_) => r);
  }
}

// ---- lib/src/strict/aggregate.dart ----


/// Materializes any iterable into a [List].
///
/// Port of FxTS `toArray` (sync); named `toList` to match Dart's
/// `Iterable.toList` (Dart has no "array" type — this always returns a [List]).
List<A> toList<A>(Iterable<A> iterable) => List.of(iterable);

/// Materializes an [FxAsyncIterable] into a [List].
///
/// Port of FxTS `toArray` (async); named `toListAsync` for Dart idiom.
Future<List<A>> toListAsync<A>(FxAsyncIterable<A> iterable) async {
  final result = <A>[];
  // Push execution where it applies — a stream source, a concurrency pool,
  // or a fused stage run — instead of pulling element by element. All three
  // are observably identical for an all-consuming terminal.
  final drive =
      fxStreamDrive<A>(iterable, result.add) ??
          fxPoolDrive<A>(iterable, result.add) ??
          fxFusedDrive<A>(iterable, result.add);
  if (drive != null) {
    await drive;
    return result;
  }
  final iterator = iterable.iterator;
  // Terminals own their iterator and consume serially, so they may use the
  // internal fast-pull path: synchronously answered pulls (fused stages
  // over a sync source) collect with no futures at all.
  if (iterator is FxFastIterator<A>) {
    while (true) {
      final ro = iterator.nextOr();
      final r = ro is Future<IterResult<A>> ? await ro : ro;
      if (r.done) return result;
      result.add(r.value);
    }
  }
  while (true) {
    final r = await iterator.next();
    if (r.done) return result;
    result.add(r.value);
  }
}

/// Iterates over [iterable], applying [f] to each value.
///
/// Port of FxTS `each` (sync).
void each<A>(void Function(A a) f, Iterable<A> iterable) {
  for (final a in iterable) {
    f(a);
  }
}

/// Async counterpart of [each]; awaits [f] per element.
Future<void> eachAsync<A>(
    FutureOr<void> Function(A a) f, FxAsyncIterable<A> iterable) async {
  // Stream-sourced chains run by subscription (see [toListAsync]).
  final drive = fxStreamDrive<A>(iterable, f) ??
      fxPoolDrive<A>(iterable, f) ??
      fxFusedDrive<A>(iterable, f);
  if (drive != null) return drive;
  final iterator = iterable.iterator;
  // Fast-pull loop where available (see [toListAsync]); awaits only
  // genuinely asynchronous pulls and callback results.
  if (iterator is FxFastIterator<A>) {
    while (true) {
      final ro = iterator.nextOr();
      final r = ro is Future<IterResult<A>> ? await ro : ro;
      if (r.done) return;
      final v = f(r.value);
      if (v is Future) await v;
    }
  }
  while (true) {
    final r = await iterator.next();
    if (r.done) return;
    // Await only genuinely asynchronous callbacks — awaiting a sync one
    // would cost a microtask hop per element.
    final v = f(r.value);
    if (v is Future) await v;
  }
}

/// Consumes up to [n] items of [iterable] (all of them when [n] is null),
/// discarding the values — useful to force side effects of a lazy pipeline.
///
/// Port of FxTS `consume`.
void consume<A>(Iterable<A> iterable, [int? n]) {
  final iterator = iterable.iterator;
  var remaining = n;
  while ((remaining == null || remaining-- > 0) && iterator.moveNext()) {}
}

/// Async counterpart of [consume].
Future<void> consumeAsync<A>(FxAsyncIterable<A> iterable, [int? n]) async {
  final iterator = iterable.iterator;
  var remaining = n;
  while (remaining == null || remaining-- > 0) {
    final r = await iterator.next();
    if (r.done) return;
  }
}

/// Folds [iterable] through [f] using its first element as the seed.
/// Throws a [StateError] on an empty iterable.
///
/// Port of FxTS `reduce(f, iterable)`. For the seeded form use [fold].
A reduce<A>(A Function(A acc, A a) f, Iterable<A> iterable) {
  final iterator = iterable.iterator;
  if (!iterator.moveNext()) {
    throw StateError("'reduce' of empty iterable with no initial value");
  }
  var acc = iterator.current;
  while (iterator.moveNext()) {
    acc = f(acc, iterator.current);
  }
  return acc;
}

/// Folds [iterable] through [f], starting from [seed].
///
/// Port of FxTS `reduce(f, seed, iterable)` (named after Dart's
/// `Iterable.fold` since Dart cannot overload by arity).
Acc fold<A, Acc>(Acc seed, Acc Function(Acc acc, A a) f, Iterable<A> iterable) {
  var acc = seed;
  for (final a in iterable) {
    acc = f(acc, a);
  }
  return acc;
}

/// Async counterpart of [reduce].
Future<A> reduceAsync<A>(
    FutureOr<A> Function(A acc, A a) f, FxAsyncIterable<A> iterable) async {
  final iterator = iterable.iterator;
  final first = await iterator.next();
  if (first.done) {
    throw StateError("'reduce' of empty iterable with no initial value");
  }
  var acc = first.value;
  // Fast-pull loop where available (see [toListAsync]).
  if (iterator is FxFastIterator<A>) {
    while (true) {
      final ro = iterator.nextOr();
      final r = ro is Future<IterResult<A>> ? await ro : ro;
      if (r.done) return acc;
      final v = f(acc, r.value);
      acc = v is Future<A> ? await v : v;
    }
  }
  while (true) {
    final r = await iterator.next();
    if (r.done) return acc;
    // Sync accumulators continue without an await hop, as in [eachAsync].
    final v = f(acc, r.value);
    acc = v is Future<A> ? await v : v;
  }
}

/// Async counterpart of [fold].
Future<Acc> foldAsync<A, Acc>(FutureOr<Acc> seed,
    FutureOr<Acc> Function(Acc acc, A a) f, FxAsyncIterable<A> iterable) async {
  var acc = seed is Future<Acc> ? await seed : seed;
  // Stream-sourced chains fold by subscription (see [toListAsync]).
  FutureOr<void> accumulate(A a) {
    final v = f(acc, a);
    if (v is Future<Acc>) {
      return v.then((next) {
        acc = next;
      });
    }
    acc = v;
  }

  final drive = fxStreamDrive<A>(iterable, accumulate) ??
      fxPoolDrive<A>(iterable, accumulate) ??
      fxFusedDrive<A>(iterable, accumulate);
  if (drive != null) {
    await drive;
    return acc;
  }
  final iterator = iterable.iterator;
  // Fast-pull loop where available (see [toListAsync]).
  if (iterator is FxFastIterator<A>) {
    while (true) {
      final ro = iterator.nextOr();
      final r = ro is Future<IterResult<A>> ? await ro : ro;
      if (r.done) return acc;
      final v = f(acc, r.value);
      acc = v is Future<Acc> ? await v : v;
    }
  }
  while (true) {
    final r = await iterator.next();
    if (r.done) return acc;
    // Sync accumulators continue without an await hop, as in [eachAsync].
    final v = f(acc, r.value);
    acc = v is Future<Acc> ? await v : v;
  }
}

/// Returns a reducer section for use in a pipeline: `reduceLazy(f, seed)`
/// gives a function `Iterable<A> -> Acc`.
///
/// Port of FxTS `reduceLazy`.
Acc Function(Iterable<A>) reduceLazy<A, Acc>(
        Acc Function(Acc acc, A a) f, Acc seed) =>
    (iterable) => fold(seed, f, iterable);

/// Adds every number in the iterable.
///
/// Port of FxTS `sum`.
@pragma('vm:prefer-inline')
num sum(Iterable<num> iterable) {
  // Monomorphic lists take an indexed loop: no iterator, and the element
  // loads stay unboxed. Values match the generic path exactly (same
  // accumulation order; empty stays the int 0).
  if (iterable is List<double>) {
    var acc = 0.0;
    final len = iterable.length;
    if (len == 0) return 0;
    for (var i = 0; i < len; i++) {
      acc += iterable[i];
    }
    return acc;
  }
  if (iterable is List<int>) {
    var acc = 0;
    final len = iterable.length;
    for (var i = 0; i < len; i++) {
      acc += iterable[i];
    }
    return acc;
  }
  // Unboxed accumulators with the boxed `num acc += v` sequence's exact
  // semantics: ints accumulate in an int until the first double arrives,
  // then accumulation switches to double seeded with the int total — the
  // same value the num fold would hold at every step.
  var iacc = 0;
  var dacc = 0.0;
  var isInt = true;
  for (final v in iterable) {
    if (isInt) {
      if (v is int) {
        iacc += v;
        continue;
      }
      dacc = iacc.toDouble();
      isInt = false;
    }
    dacc += v;
  }
  return isInt ? iacc : dacc;
}

/// Sums the key [f] of every element — `map` + [sum] in one step, so a
/// pipeline that only needs a field total doesn't spell out the projection.
///
/// Empty input returns `0` (the [sum] contract).
///
/// Dart-native addition (FxTS has only the numeric `sum`); named after
/// [maxBy]/[minBy] — Kotlin spells it `sumOf`.
@pragma('vm:prefer-inline')
num sumBy<A>(num Function(A a) f, Iterable<A> iterable) {
  // Same unboxed int-then-double accumulation as [sum]; lists iterate by
  // index so no iterator is allocated.
  var iacc = 0;
  var dacc = 0.0;
  var isInt = true;
  if (iterable is List<A>) {
    final len = iterable.length;
    for (var i = 0; i < len; i++) {
      final v = f(iterable[i]);
      if (isInt) {
        if (v is int) {
          iacc += v;
          continue;
        }
        dacc = iacc.toDouble();
        isInt = false;
      }
      dacc += v;
    }
    return isInt ? iacc : dacc;
  }
  for (final a in iterable) {
    final v = f(a);
    if (isInt) {
      if (v is int) {
        iacc += v;
        continue;
      }
      dacc = iacc.toDouble();
      isInt = false;
    }
    dacc += v;
  }
  return isInt ? iacc : dacc;
}

/// Async counterpart of [sumBy].
Future<num> sumByAsync<A>(
        FutureOr<num> Function(A a) f, FxAsyncIterable<A> iterable) =>
    foldAsync<A, num>(0, (acc, a) async => acc + await f(a), iterable);

/// Async counterpart of [sum].
Future<num> sumAsync(FxAsyncIterable<num> iterable) =>
    foldAsync<num, num>(0, (a, b) => a + b, iterable);

/// Concatenates every string in the iterable.
String sumStrings(Iterable<String> iterable) =>
    fold('', (a, b) => a + b, iterable);

/// Returns the average of the numbers. `NaN` for an empty iterable.
///
/// Port of FxTS `average`.
@pragma('vm:prefer-inline')
double average(Iterable<num> iterable) {
  // Monomorphic-list fast paths, as in [sum].
  if (iterable is List<double>) {
    final len = iterable.length;
    if (len == 0) return double.nan;
    var acc = 0.0;
    for (var i = 0; i < len; i++) {
      acc += iterable[i];
    }
    return acc / len;
  }
  if (iterable is List<int>) {
    final len = iterable.length;
    if (len == 0) return double.nan;
    var acc = 0;
    for (var i = 0; i < len; i++) {
      acc += iterable[i];
    }
    return acc / len;
  }
  // Same unboxed int-then-double accumulation as [sum].
  var size = 0;
  var iacc = 0;
  var dacc = 0.0;
  var isInt = true;
  for (final v in iterable) {
    size++;
    if (isInt) {
      if (v is int) {
        iacc += v;
        continue;
      }
      dacc = iacc.toDouble();
      isInt = false;
    }
    dacc += v;
  }
  if (size == 0) return double.nan;
  return isInt ? iacc / size : dacc / size;
}

/// Async counterpart of [average].
Future<double> averageAsync(FxAsyncIterable<num> iterable) async {
  var size = 0;
  num total = 0;
  await eachAsync((num a) {
    size++;
    total += a;
  }, iterable);
  return size == 0 ? double.nan : total / size;
}

/// Averages the key [f] of every element — `map` + [average] in one step.
///
/// Empty input returns `double.nan` (the [average] contract).
///
/// Dart-native addition completing the by-key family
/// ([sumBy] / [maxBy] / [minBy]).
@pragma('vm:prefer-inline')
double averageBy<A>(num Function(A a) f, Iterable<A> iterable) {
  if (iterable is List<A>) {
    final len = iterable.length;
    if (len == 0) return double.nan;
    var total = 0.0;
    for (var i = 0; i < len; i++) {
      total += f(iterable[i]);
    }
    return total / len;
  }
  var total = 0.0;
  var count = 0;
  for (final a in iterable) {
    total += f(a);
    count++;
  }
  return count == 0 ? double.nan : total / count;
}

/// Async counterpart of [averageBy].
Future<double> averageByAsync<A>(
    FutureOr<num> Function(A a) f, FxAsyncIterable<A> iterable) async {
  var total = 0.0;
  var count = 0;
  await eachAsync((A a) async {
    total += await f(a);
    count++;
  }, iterable);
  return count == 0 ? double.nan : total / count;
}

num _minOf(num acc, num a) => a.isNaN || acc.isNaN
    ? double.nan
    : a < acc
        ? a
        : acc;

num _maxOf(num acc, num a) => a.isNaN || acc.isNaN
    ? double.nan
    : a > acc
        ? a
        : acc;

/// Returns the smallest number; `infinity` for an empty iterable, `NaN` if
/// any element is `NaN` — mirroring FxTS `min`.
@pragma('vm:prefer-inline')
num min(Iterable<num> iterable) {
  // Monomorphic-list fast paths, as in [sum]; results match the [_minOf]
  // fold exactly (empty → infinity, any NaN → NaN, strict < keeps the
  // first of equal values).
  if (iterable is List<double>) {
    final length = iterable.length;
    var acc = double.infinity;
    var hasNaN = false;
    for (var i = 0; i < length; i++) {
      final v = iterable[i];
      if (v.isNaN) hasNaN = true;
      if (v < acc) acc = v;
    }
    return hasNaN ? double.nan : acc;
  }
  if (iterable is List<int>) {
    final length = iterable.length;
    if (length == 0) return double.infinity;
    var acc = iterable[0];
    for (var i = 1; i < length; i++) {
      final v = iterable[i];
      if (v < acc) acc = v;
    }
    return acc;
  }
  num acc = double.infinity;
  for (final v in iterable) {
    acc = _minOf(acc, v);
  }
  return acc;
}

/// Async counterpart of [min].
Future<num> minAsync(FxAsyncIterable<num> iterable) =>
    foldAsync(double.infinity, _minOf, iterable);

/// Returns the largest number; `-infinity` for an empty iterable, `NaN` if
/// any element is `NaN` — mirroring FxTS `max`.
@pragma('vm:prefer-inline')
num max(Iterable<num> iterable) {
  // Mirror image of [min]'s fast paths.
  if (iterable is List<double>) {
    final length = iterable.length;
    var acc = -double.infinity;
    var hasNaN = false;
    for (var i = 0; i < length; i++) {
      final v = iterable[i];
      if (v.isNaN) hasNaN = true;
      if (v > acc) acc = v;
    }
    return hasNaN ? double.nan : acc;
  }
  if (iterable is List<int>) {
    final length = iterable.length;
    if (length == 0) return -double.infinity;
    var acc = iterable[0];
    for (var i = 1; i < length; i++) {
      final v = iterable[i];
      if (v > acc) acc = v;
    }
    return acc;
  }
  num acc = -double.infinity;
  for (final v in iterable) {
    acc = _maxOf(acc, v);
  }
  return acc;
}

/// Async counterpart of [max].
Future<num> maxAsync(FxAsyncIterable<num> iterable) =>
    foldAsync(-double.infinity, _maxOf, iterable);

/// Returns the element whose key [f] is smallest, or `null` when empty.
///
/// Keys are compared like [sortBy] compares them ([Comparable.compare]);
/// on ties the **first** encountered element wins. One O(n) walk — no sort.
///
/// Dart-native addition (FxTS has only numeric `min`); named after Kotlin's
/// `minByOrNull` shape, nullable like [head]/[last].
A? minBy<A>(Object? Function(A a) f, Iterable<A> iterable) {
  A? best;
  Object? bestKey;
  var seen = false;
  for (final a in iterable) {
    // The key of the running best is extracted once and cached; [f] runs
    // exactly once per element.
    final key = f(a);
    if (!seen || _compareKeys(key, bestKey) < 0) {
      best = a;
      bestKey = key;
      seen = true;
    }
  }
  return best;
}

/// Async counterpart of [minBy].
Future<A?> minByAsync<A>(
    Object? Function(A a) f, FxAsyncIterable<A> iterable) async {
  A? best;
  var seen = false;
  await eachAsync((A a) {
    if (!seen || _compareBy(f, a, best as A) < 0) {
      best = a;
      seen = true;
    }
  }, iterable);
  return best;
}

/// Returns the element whose key [f] is largest, or `null` when empty.
///
/// Keys are compared like [sortBy] compares them ([Comparable.compare]);
/// on ties the **first** encountered element wins. One O(n) walk — no sort.
///
/// Dart-native addition (FxTS has only numeric `max`); named after Kotlin's
/// `maxByOrNull` shape, nullable like [head]/[last].
A? maxBy<A>(Object? Function(A a) f, Iterable<A> iterable) {
  A? best;
  Object? bestKey;
  var seen = false;
  for (final a in iterable) {
    final key = f(a);
    if (!seen || _compareKeys(key, bestKey) > 0) {
      best = a;
      bestKey = key;
      seen = true;
    }
  }
  return best;
}

/// Async counterpart of [maxBy].
Future<A?> maxByAsync<A>(
    Object? Function(A a) f, FxAsyncIterable<A> iterable) async {
  A? best;
  var seen = false;
  await eachAsync((A a) {
    if (!seen || _compareBy(f, a, best as A) > 0) {
      best = a;
      seen = true;
    }
  }, iterable);
  return best;
}

/// Returns the number of elements.
///
/// Port of FxTS `size`. O(1) for a [List] or [Set].
@pragma('vm:prefer-inline')
int size<A>(Iterable<A> iterable) {
  if (iterable is List || iterable is Set) return iterable.length;
  var n = 0;
  for (final _ in iterable) {
    n++;
  }
  return n;
}

/// Async counterpart of [size].
Future<int> sizeAsync<A>(FxAsyncIterable<A> iterable) async {
  var n = 0;
  await eachAsync((_) => n++, iterable);
  return n;
}

/// Counts the values [f] holds for — `filter` + `size` in one walk.
///
/// Dart-native addition (Kotlin's `count { }`).
int countWhere<A>(bool Function(A a) f, Iterable<A> iterable) {
  var n = 0;
  for (final a in iterable) {
    if (f(a)) n++;
  }
  return n;
}

/// Async counterpart of [countWhere].
Future<int> countWhereAsync<A>(
    FutureOr<bool> Function(A a) f, FxAsyncIterable<A> iterable) async {
  var n = 0;
  await eachAsync((A a) async {
    if (await f(a)) n++;
  }, iterable);
  return n;
}

/// Returns all elements joined into a string, separated by [sep].
///
/// Port of FxTS `join`.
String join<A>(String sep, Iterable<A> iterable) => iterable.join(sep);

/// Async counterpart of [join].
Future<String> joinAsync<A>(String sep, FxAsyncIterable<A> iterable) async =>
    (await toListAsync(iterable)).join(sep);

/// Splits values into groups keyed by [f].
///
/// Port of FxTS `groupBy` (TS objects become Dart Maps).
Map<K, List<A>> groupBy<A, K>(K Function(A a) f, Iterable<A> iterable) {
  final result = <K, List<A>>{};
  // `??=` instead of putIfAbsent: putIfAbsent allocates an ifAbsent closure
  // per element.
  for (final a in iterable) {
    (result[f(a)] ??= []).add(a);
  }
  return result;
}

/// Async counterpart of [groupBy].
Future<Map<K, List<A>>> groupByAsync<A, K>(
    FutureOr<K> Function(A a) f, FxAsyncIterable<A> iterable) async {
  final result = <K, List<A>>{};
  await eachAsync(
      (A a) async => result.putIfAbsent(await f(a), () => []).add(a), iterable);
  return result;
}

/// Groups values into `(key, items)` records, in first-seen key order —
/// the chainable view of [groupBy], so per-group aggregation continues in
/// the same pipeline instead of re-entering through `Map.entries`.
///
/// Dart-native addition (no FxTS counterpart).
///
/// ```dart
/// groupedBy((w) => w.length, ['ab', 'cd', 'e']);
/// // [(key: 2, items: [ab, cd]), (key: 1, items: [e])]
/// ```
List<({K key, List<A> items})> groupedBy<A, K>(
        K Function(A a) f, Iterable<A> iterable) =>
    [
      for (final e in groupBy(f, iterable).entries) (key: e.key, items: e.value)
    ];

/// Async counterpart of [groupedBy].
Future<List<({K key, List<A> items})>> groupedByAsync<A, K>(
        FutureOr<K> Function(A a) f, FxAsyncIterable<A> iterable) async =>
    [
      for (final e in (await groupByAsync(f, iterable)).entries)
        (key: e.key, items: e.value)
    ];

/// Indexes values by [f]; later duplicates overwrite earlier ones.
///
/// Port of FxTS `indexBy`.
Map<K, A> indexBy<A, K>(K Function(A a) f, Iterable<A> iterable) {
  final result = <K, A>{};
  for (final a in iterable) {
    result[f(a)] = a;
  }
  return result;
}

/// Async counterpart of [indexBy].
Future<Map<K, A>> indexByAsync<A, K>(
    FutureOr<K> Function(A a) f, FxAsyncIterable<A> iterable) async {
  final result = <K, A>{};
  await eachAsync((A a) async => result[await f(a)] = a, iterable);
  return result;
}

/// Counts occurrences of each key produced by [f].
///
/// Port of FxTS `countBy`.
Map<K, int> countBy<A, K>(K Function(A a) f, Iterable<A> iterable) {
  final result = <K, int>{};
  // Read-modify-write instead of Map.update: update allocates two closures
  // per element.
  for (final a in iterable) {
    final k = f(a);
    result[k] = (result[k] ?? 0) + 1;
  }
  return result;
}

/// Async counterpart of [countBy].
Future<Map<K, int>> countByAsync<A, K>(
    FutureOr<K> Function(A a) f, FxAsyncIterable<A> iterable) async {
  final result = <K, int>{};
  await eachAsync(
      (A a) async => result.update(await f(a), (n) => n + 1, ifAbsent: () => 1),
      iterable);
  return result;
}

/// Returns a **new** sorted list ordered by the comparator [f].
///
/// Port of FxTS `sort`. Unlike the TS version (which mutates arrays in
/// place), the Dart port never mutates its input.
List<A> sort<A>(int Function(A a, A b) f, Iterable<A> iterable) =>
    List.of(iterable)..sort(f);

/// Async counterpart of [sort].
Future<List<A>> sortAsync<A>(
        int Function(A a, A b) f, FxAsyncIterable<A> iterable) async =>
    (await toListAsync(iterable))..sort(f);

/// Alias of [sort]; FxTS added `toSorted` as the non-mutating variant, which
/// the Dart [sort] already is.
List<A> toSorted<A>(int Function(A a, A b) f, Iterable<A> iterable) =>
    sort(f, iterable);

int _compareKeys(Object? fa, Object? fb) {
  if (fa is Comparable && fb is Comparable) {
    return Comparable.compare(
        fa as Comparable<Object?>, fb as Comparable<Object?>);
  }
  return 0;
}

int _compareBy<A>(Object? Function(A a) f, A a, A b) => _compareKeys(f(a), f(b));

/// Returns a new list sorted by the key extractor [f] (ascending).
///
/// Port of FxTS `sortBy`.
List<A> sortBy<A>(Object? Function(A a) f, Iterable<A> iterable) =>
    _sortByImpl(f, iterable, false);

/// Returns a new list sorted by the key extractor [f], descending.
///
/// The symmetric twin of [sortBy] (Kotlin's `sortedByDescending`) — works
/// for any comparable key, unlike the numeric-only `sortBy((a) => -key)`
/// negation trick.
List<A> sortByDesc<A>(Object? Function(A a) f, Iterable<A> iterable) =>
    _sortByImpl(f, iterable, true);

List<A> _sortByImpl<A>(
    Object? Function(A a) f, Iterable<A> iterable, bool desc) {
  // Decorate-sort-undecorate: extract each key once, sort an index list, and
  // read the permutation back. Sorting the values directly with a
  // `_compareBy` comparator would call [f] twice per comparison —
  // 2·n·log n extractions instead of n. The permutation is identical to the
  // direct sort's: sort decisions depend only on comparator outcomes, and
  // the index comparator returns exactly what the direct comparator would.
  final items = List.of(iterable);
  final length = items.length;
  if (length < 2) return items;
  final keys = [for (final a in items) f(a)];
  final indices = [for (var i = 0; i < length; i++) i];

  // Homogeneous key types get an unboxed key array and a devirtualized
  // compareTo — the generic path pays an `is Comparable` test and a dynamic
  // compareTo on every comparison. compareTo semantics (NaN, -0.0) are the
  // same on every path. No Int64List: the playground build targets JS.
  // Descending picks a swapped-operand comparator once per sort, so the
  // per-comparison cost is identical to ascending.
  var allDouble = true, allInt = true, allString = true;
  for (final k in keys) {
    if (k is! double) allDouble = false;
    if (k is! int) allInt = false;
    if (k is! String) allString = false;
    if (!(allDouble || allInt || allString)) break;
  }
  if (allDouble) {
    final dk = Float64List(length);
    for (var i = 0; i < length; i++) {
      dk[i] = keys[i] as double;
    }
    indices.sort(desc
        ? (i, j) => dk[j].compareTo(dk[i])
        : (i, j) => dk[i].compareTo(dk[j]));
  } else if (allInt) {
    final ik = List<int>.filled(length, 0);
    for (var i = 0; i < length; i++) {
      ik[i] = keys[i] as int;
    }
    indices.sort(desc
        ? (i, j) => ik[j].compareTo(ik[i])
        : (i, j) => ik[i].compareTo(ik[j]));
  } else if (allString) {
    final sk = List<String>.filled(length, '');
    for (var i = 0; i < length; i++) {
      sk[i] = keys[i] as String;
    }
    indices.sort(desc
        ? (i, j) => sk[j].compareTo(sk[i])
        : (i, j) => sk[i].compareTo(sk[j]));
  } else {
    indices.sort(desc
        ? (i, j) => _compareKeys(keys[j], keys[i])
        : (i, j) => _compareKeys(keys[i], keys[j]));
  }
  return [for (final i in indices) items[i]];
}

/// Async counterpart of [sortBy].
Future<List<A>> sortByAsync<A>(
        Object? Function(A a) f, FxAsyncIterable<A> iterable) =>
    sortAsync((a, b) => _compareBy(f, a, b), iterable);

/// Async counterpart of [sortByDesc].
Future<List<A>> sortByDescAsync<A>(
        Object? Function(A a) f, FxAsyncIterable<A> iterable) =>
    sortAsync((a, b) => _compareBy(f, b, a), iterable);

/// Splits values into `(pass, fail)` lists by predicate [f].
///
/// Port of FxTS `partition` (TS tuple becomes a Dart record).
(List<A>, List<A>) partition<A>(bool Function(A a) f, Iterable<A> iterable) {
  final pass = <A>[];
  final fail = <A>[];
  for (final a in iterable) {
    (f(a) ? pass : fail).add(a);
  }
  return (pass, fail);
}

/// Async counterpart of [partition].
Future<(List<A>, List<A>)> partitionAsync<A>(
    FutureOr<bool> Function(A a) f, FxAsyncIterable<A> iterable) async {
  final pass = <A>[];
  final fail = <A>[];
  await eachAsync((A a) async => (await f(a) ? pass : fail).add(a), iterable);
  return (pass, fail);
}

// --- tee: several folds over one pass -------------------------------------

/// One reduction in a [tee] / [tee3] pass: where it starts, and how each
/// element advances it.
typedef Fold<A, R> = ({R seed, R Function(R acc, A a) step});

/// Runs two folds over a **single** pass of [iterable], returning both
/// results.
///
/// [fork] can also feed two readers from one pass, but only by buffering:
/// its cursors advance independently, so draining one before the other holds
/// every element the lagging cursor has not reached. Expressing the readers
/// as folds instead lets both advance on the same element, so the pass costs
/// no memory at all — the counterpart of Rx's `publish()`, where attaching
/// both subscribers before `connect()` is what avoids the buffer.
///
/// The source is iterated exactly once, so a side-effecting or single-shot
/// iterable is safe. Both steps see every element, in order.
///
/// fxdart extension (not part of FxTS).
///
/// ```dart
/// final (total, peak) = tee(readings,
///     (seed: 0, step: (int a, int r) => a + r),
///     (seed: 0, step: (int a, int r) => r > a ? r : a));
/// ```
@pragma('vm:align-loops')
(R1, R2) tee<A, R1, R2>(
    Iterable<A> iterable, Fold<A, R1> first, Fold<A, R2> second) {
  final f1 = first.step;
  final f2 = second.step;
  var a1 = first.seed;
  var a2 = second.seed;
  for (final a in iterable) {
    a1 = f1(a1, a);
    a2 = f2(a2, a);
  }
  return (a1, a2);
}

/// Three-fold [tee].
@pragma('vm:align-loops')
(R1, R2, R3) tee3<A, R1, R2, R3>(Iterable<A> iterable, Fold<A, R1> first,
    Fold<A, R2> second, Fold<A, R3> third) {
  final f1 = first.step;
  final f2 = second.step;
  final f3 = third.step;
  var a1 = first.seed;
  var a2 = second.seed;
  var a3 = third.seed;
  for (final a in iterable) {
    a1 = f1(a1, a);
    a2 = f2(a2, a);
    a3 = f3(a3, a);
  }
  return (a1, a2, a3);
}

/// Async counterpart of [tee]. Steps may return a [Future]; each element is
/// applied to both accumulators before the next is pulled.
Future<(R1, R2)> teeAsync<A, R1, R2>(FxAsyncIterable<A> iterable,
    AsyncFold<A, R1> first, AsyncFold<A, R2> second) async {
  final f1 = first.step;
  final f2 = second.step;
  var a1 = await first.seed;
  var a2 = await second.seed;
  await eachAsync((A a) {
    final r1 = f1(a1, a);
    if (r1 is Future<R1>) {
      return r1.then((v1) {
        a1 = v1;
        final r2 = f2(a2, a);
        if (r2 is Future<R2>) return r2.then((v2) => a2 = v2);
        a2 = r2;
      });
    }
    a1 = r1;
    final r2 = f2(a2, a);
    if (r2 is Future<R2>) return r2.then((v2) => a2 = v2);
    a2 = r2;
  }, iterable);
  return (a1, a2);
}

/// The [teeAsync] counterpart of [Fold].
typedef AsyncFold<A, R> = ({
  FutureOr<R> seed,
  FutureOr<R> Function(R acc, A a) step
});

// ---- lib/src/strict/access.dart ----


/// Returns the first element, or `null` when empty.
///
/// Port of FxTS `head` (TS `undefined` becomes Dart `null`).
A? head<A>(Iterable<A> iterable) {
  final iterator = iterable.iterator;
  return iterator.moveNext() ? iterator.current : null;
}

/// Async counterpart of [head].
Future<A?> headAsync<A>(FxAsyncIterable<A> iterable) async {
  final r = await iterable.iterator.next();
  return r.done ? null : r.value;
}

/// Returns the last element, or `null` when empty.
///
/// Port of FxTS `last`. O(1) for a [List].
@pragma('vm:prefer-inline')
A? last<A>(Iterable<A> iterable) {
  if (iterable is List<A>) {
    final length = iterable.length;
    return length == 0 ? null : iterable[length - 1];
  }
  A? result;
  for (final a in iterable) {
    result = a;
  }
  return result;
}

/// Async counterpart of [last].
Future<A?> lastAsync<A>(FxAsyncIterable<A> iterable) async {
  final iterator = iterable.iterator;
  A? result;
  while (true) {
    final r = await iterator.next();
    if (r.done) return result;
    result = r.value;
  }
}

/// Returns the element at [index], or `null` when out of range.
///
/// Port of FxTS `nth`. O(1) for a [List].
@pragma('vm:prefer-inline')
A? nth<A>(int index, Iterable<A> iterable) {
  if (index < 0) return null;
  if (iterable is List<A>) {
    return index < iterable.length ? iterable[index] : null;
  }
  var i = 0;
  for (final a in iterable) {
    if (i++ == index) return a;
  }
  return null;
}

/// Async counterpart of [nth].
Future<A?> nthAsync<A>(int index, FxAsyncIterable<A> iterable) async {
  if (index < 0) return null;
  final iterator = iterable.iterator;
  var i = 0;
  while (true) {
    final r = await iterator.next();
    if (r.done) return null;
    if (i++ == index) return r.value;
  }
}

/// Returns the first element [f] returns true for, or `null`.
///
/// Port of FxTS `find`. A direct loop, not `head(filter(...))` — the filter
/// layer would cost an iterator allocation plus two indirect calls per
/// element; lists iterate by index.
@pragma('vm:prefer-inline')
A? find<A>(bool Function(A a) f, Iterable<A> iterable) {
  if (iterable is List<A>) {
    final length = iterable.length;
    for (var i = 0; i < length; i++) {
      final a = iterable[i];
      if (f(a)) return a;
    }
    return null;
  }
  for (final a in iterable) {
    if (f(a)) return a;
  }
  return null;
}

/// Async counterpart of [find].
Future<A?> findAsync<A>(
        FutureOr<bool> Function(A a) f, FxAsyncIterable<A> iterable) =>
    headAsync(filterAsync(f, iterable));

/// Returns the index of the first element [f] returns true for, or `-1`.
///
/// Port of FxTS `findIndex`. A counted direct loop, not `zipWithIndex` —
/// the zip layer would allocate an `(int, A)` record per element.
@pragma('vm:prefer-inline')
int findIndex<A>(bool Function(A a) f, Iterable<A> iterable) {
  if (iterable is List<A>) {
    final length = iterable.length;
    for (var i = 0; i < length; i++) {
      if (f(iterable[i])) return i;
    }
    return -1;
  }
  var i = 0;
  for (final a in iterable) {
    if (f(a)) return i;
    i++;
  }
  return -1;
}

/// Async counterpart of [findIndex].
Future<int> findIndexAsync<A>(
    FutureOr<bool> Function(A a) f, FxAsyncIterable<A> iterable) async {
  final result = await findAsync((r) => f(r.$2), zipWithIndexAsync(iterable));
  return result == null ? -1 : result.$1;
}

/// Returns true when the iterable contains [a] (`==` comparison).
///
/// Port of FxTS `includes`.
bool includes<A>(A a, Iterable<A> iterable) => iterable.contains(a);

/// Async counterpart of [includes].
Future<bool> includesAsync<A>(A a, FxAsyncIterable<A> iterable) =>
    someAsync((A b) => b == a, iterable);

/// Returns true when every element satisfies [f] (true for an empty
/// iterable). Short-circuits.
///
/// Port of FxTS `every`.
bool every<A>(bool Function(A a) f, Iterable<A> iterable) {
  for (final a in iterable) {
    if (!f(a)) return false;
  }
  return true;
}

/// Async counterpart of [every].
Future<bool> everyAsync<A>(
    FutureOr<bool> Function(A a) f, FxAsyncIterable<A> iterable) async {
  final iterator = iterable.iterator;
  while (true) {
    final r = await iterator.next();
    if (r.done) return true;
    if (!await f(r.value)) return false;
  }
}

/// Returns true when at least one element satisfies [f] (false for an empty
/// iterable). Short-circuits.
///
/// Port of FxTS `some`.
bool some<A>(bool Function(A a) f, Iterable<A> iterable) {
  for (final a in iterable) {
    if (f(a)) return true;
  }
  return false;
}

/// Async counterpart of [some].
Future<bool> someAsync<A>(
    FutureOr<bool> Function(A a) f, FxAsyncIterable<A> iterable) async {
  final iterator = iterable.iterator;
  while (true) {
    final r = await iterator.next();
    if (r.done) return false;
    if (await f(r.value)) return true;
  }
}

/// Value-based emptiness check: true for `null`, `''`, and empty
/// [Iterable]/[Map]/[Set]; false for everything else (numbers, booleans,
/// functions, arbitrary objects).
///
/// Port of FxTS `isEmpty`.
bool isEmpty(Object? value) {
  if (value == null) return true;
  if (value is String) return value.isEmpty;
  if (value is Iterable) return value.isEmpty;
  if (value is Map) return value.isEmpty;
  return false;
}

// ---- lib/src/strict/object.dart ----

/// Builds a map from `(key, value)` records.
///
/// Port of FxTS `fromEntries` (TS entry tuples become Dart records).
///
/// ```dart
/// fromEntries([('a', 1), ('b', 2)]); // {a: 1, b: 2}
/// ```
Map<K, V> fromEntries<K, V>(Iterable<(K, V)> entries) =>
    {for (final (k, v) in entries) k: v};

/// Returns a copy of [map] without the given [keysToOmit].
///
/// Port of FxTS `omit`.
Map<K, V> omit<K, V>(Iterable<K> keysToOmit, Map<K, V> map) {
  final set = keysToOmit.toSet();
  return {
    for (final e in map.entries)
      if (!set.contains(e.key)) e.key: e.value
  };
}

/// Returns a copy of [map] with only the given [keysToPick].
///
/// Port of FxTS `pick`.
Map<K, V> pick<K, V>(Iterable<K> keysToPick, Map<K, V> map) {
  final set = keysToPick.toSet();
  return {
    for (final e in map.entries)
      if (set.contains(e.key)) e.key: e.value
  };
}

/// Returns a copy of [map] without entries matching the predicate [f].
///
/// Port of FxTS `omitBy` (entry tuples become records).
Map<K, V> omitBy<K, V>(bool Function((K, V) entry) f, Map<K, V> map) => {
      for (final e in map.entries)
        if (!f((e.key, e.value))) e.key: e.value
    };

/// Returns a copy of [map] with only entries matching the predicate [f].
///
/// Port of FxTS `pickBy`.
Map<K, V> pickBy<K, V>(bool Function((K, V) entry) f, Map<K, V> map) => {
      for (final e in map.entries)
        if (f((e.key, e.value))) e.key: e.value
    };

/// Returns the value of [key] in [map], or `null`.
///
/// Port of FxTS `prop`.
V? prop<K, V>(K key, Map<K, V> map) => map[key];

/// Returns the values of [propKeys] in [map] (missing keys yield `null`).
///
/// Port of FxTS `props`.
List<V?> props<K, V>(Iterable<K> propKeys, Map<K, V> map) =>
    [for (final k in propKeys) map[k]];

/// Returns a copy of [map] with `null` values removed (shallow).
///
/// Port of FxTS `compactObject`.
Map<K, V> compactObject<K, V>(Map<K, V?> map) => {
      for (final e in map.entries) e.key: ?e.value
    };

/// Creates a new map by running each value whose key appears in
/// [transformations] through its transformation function.
///
/// Port of FxTS `evolve`. Untransformed keys are kept as-is.
Map<K, Object?> evolve<K>(
    Map<K, Object? Function(Object? value)> transformations,
    Map<K, Object?> map) {
  return {
    for (final e in map.entries)
      e.key: transformations.containsKey(e.key)
          ? transformations[e.key]!(e.value)
          : e.value
  };
}

/// Awaits every value of the map — the async analogue of `Future.wait` for
/// maps.
///
/// Port of FxTS `resolveProps`.
///
/// ```dart
/// await resolveProps({'a': Future.value(1), 'b': 2}); // {a: 1, b: 2}
/// ```
Future<Map<K, V>> resolveProps<K, V>(Map<K, FutureOr<V>> map) async {
  final result = <K, V>{};
  for (final e in map.entries) {
    result[e.key] = await e.value;
  }
  return result;
}

/// Deep partial match: checks whether [target] contains everything in
/// [pattern]. Maps match when every pattern entry matches recursively;
/// iterables match pairwise; anything else compares with `==`.
///
/// Port of FxTS `isMatch`.
bool isMatch(Object? target, Object? pattern) {
  if (pattern is Map) {
    if (target is! Map) return false;
    for (final e in pattern.entries) {
      if (!target.containsKey(e.key) || !isMatch(target[e.key], e.value)) {
        return false;
      }
    }
    return true;
  }
  if (pattern is Iterable) {
    if (target is! Iterable) return false;
    final ti = target.iterator;
    final pi = pattern.iterator;
    while (pi.moveNext()) {
      if (!ti.moveNext() || !isMatch(ti.current, pi.current)) return false;
    }
    // FxTS matches when the pattern is a prefix of the target.
    return true;
  }
  return target == pattern;
}

/// Curried [isMatch]: returns a predicate that matches against [pattern].
///
/// Port of FxTS `matches`.
bool Function(Object? target) matches(Object? pattern) =>
    (target) => isMatch(target, pattern);

// ---- lib/src/strict/func.dart ----

/// Adds two values. Works for any type supporting `+` ([num], [String],
/// [List], ...) — mirrors FxTS `add`, which accepts numbers and strings.
T add<T extends Object>(T a, T b) => (a as dynamic) + b as T;

/// Returns a function that always returns [a], ignoring an optional
/// argument (so it can be used as a unary callback).
///
/// Port of FxTS `always`.
T Function([Object? _]) always<T>(T a) => ([Object? _]) => a;

/// Calls [f] with [args] as positional arguments.
///
/// Port of FxTS `apply`.
R apply<R>(Function f, List<Object?> args) => Function.apply(f, args) as R;

/// Returns its argument unchanged.
///
/// Port of FxTS `identity`.
T identity<T>(T a) => a;

/// Does nothing.
///
/// Port of FxTS `noop`.
void noop() {}

/// Boolean negation.
///
/// Port of FxTS `not` (Dart has no truthiness, so this takes a [bool]).
bool not(bool a) => !a;

/// Returns a predicate that negates [f].
///
/// Port of FxTS `negate`.
bool Function(T) negate<T>(bool Function(T) f) => (a) => !f(a);

/// Calls [f] with [a] for its side effect, then returns [a].
///
/// Port of FxTS `tap` (data-first; close over [f] for the curried style).
T tap<T>(void Function(T a) f, T a) {
  f(a);
  return a;
}

/// Returns `callback(value)` when the predicate holds, otherwise [value].
///
/// Port of FxTS `when`. TS can widen the return union `T | R`; in Dart both
/// branches must share the type [T].
T when<T>(bool Function(T) predicate, T Function(T) callback, T value) =>
    predicate(value) ? callback(value) : value;

/// The opposite of [when]: applies [callback] when the predicate fails.
///
/// Port of FxTS `unless`.
T unless<T>(bool Function(T) predicate, T Function(T) callback, T value) =>
    predicate(value) ? value : callback(value);

/// Returns a unary function that throws `toError(value)`.
///
/// Port of FxTS `throwError`.
Never Function(T) throwError<T>(Object Function(T) toError) =>
    (a) => throw toError(a);

/// Throws `toError(value)` when the predicate holds; otherwise returns
/// [value] unchanged.
///
/// Port of FxTS `throwIf`.
T throwIf<T>(bool Function(T) predicate, Object Function(T) toError, T value) {
  if (predicate(value)) throw toError(value);
  return value;
}

int _compare(Object? a, Object? b) {
  if (a is Comparable && b is Comparable) {
    if (a.runtimeType != b.runtimeType &&
        !(a is num && b is num) &&
        !(a is String && b is String)) {
      throw ArgumentError(
          'The values you want to compare must be of the same type');
    }
    return Comparable.compare(
        a as Comparable<Object?>, b as Comparable<Object?>);
  }
  throw ArgumentError('The values must be Comparable');
}

/// `a > b`. Port of FxTS `gt` (data-first; use a closure for currying:
/// `(b) => gt(5, b)`).
bool gt(Object? a, Object? b) => _compare(a, b) > 0;

/// `a >= b`. Port of FxTS `gte`.
bool gte(Object? a, Object? b) => _compare(a, b) >= 0;

/// `a < b`. Port of FxTS `lt`.
bool lt(Object? a, Object? b) => _compare(a, b) < 0;

/// `a <= b`. Port of FxTS `lte`.
bool lte(Object? a, Object? b) => _compare(a, b) <= 0;

/// Applies every function in [fns] to [a] and collects the results.
///
/// Port of FxTS `juxt` (unary form — Dart has no variadic generics).
///
/// ```dart
/// juxt([min, max])([3, 4, 9, 1]); // [1, 9]
/// ```
List<R> Function(T a) juxt<T, R>(List<R Function(T a)> fns) =>
    (a) => [for (final f in fns) f(a)];

/// Memoizes a unary function by its argument (`==`/`hashCode` keyed).
///
/// Port of FxTS `memoize` (unary only; TS's variadic/`WeakMap` behavior has
/// no Dart equivalent).
R Function(A) memoize<A, R>(R Function(A) f) {
  final cache = <A, R>{};
  return (a) => cache.putIfAbsent(a, () => f(a));
}

/// Returns a [Future] that completes with [value] after [wait].
///
/// Port of FxTS `delay`.
///
/// ```dart
/// await delay(Duration(seconds: 1), 'a'); // 'a' after 1s
/// ```
Future<T> delay<T>(Duration wait, T value) => Future.delayed(wait, () => value);

/// Returns a [Future] that completes after [wait].
Future<void> sleep(Duration wait) => Future.delayed(wait);

/// Builds a matcher from `predicate, mapper` pairs with an optional
/// default. When nothing matches and no [orElse] is given, the value itself
/// is returned (it must then be an `R`).
///
/// Port of FxTS `cases`; Dart cannot type variadic pairs, so they are passed
/// as records.
///
/// ```dart
/// final classify = cases<int, String>([
///   ((n) => n < 0, (n) => 'negative'),
///   ((n) => n == 0, (n) => 'zero'),
/// ], orElse: (n) => 'positive');
/// classify(-4); // 'negative'
/// ```
R Function(T value) cases<T, R>(List<(bool Function(T), R Function(T))> pairs,
    {R Function(T)? orElse}) {
  return (value) {
    for (final (predicate, mapper) in pairs) {
      if (predicate(value)) return mapper(value);
    }
    if (orElse != null) return orElse(value);
    if (value is R) return value;
    throw StateError('cases: no case matched and no orElse given');
  };
}

/// Splits a string into a list of user-perceived characters, handling
/// surrogate pairs — the same behavior as FxTS `unicodeToArray`, which
/// splits by code point. Named `unicodeToList` for Dart idiom (returns a List).
List<String> unicodeToList(String s) =>
    [for (final rune in s.runes) String.fromCharCode(rune)];

/// FxTS-named alias of [unicodeToList].
List<String> unicodeToArray(String s) => unicodeToList(s);

/// TypeScript's `curry` relies on reflection over a function's arity plus
/// recursive conditional types (`Curry<...>`), neither of which exists in
/// Dart. This stub only curries binary functions and is untyped. The typed,
/// Dart-native replacement is the `.curried` extension getter (arities 2–5)
/// — see `WHY_CURRIED.md`.
@Deprecated('Use the .curried extension getter instead (see WHY_CURRIED.md)')
Function curry(Function f) => (Object? a) => (Object? b) => f(a, b);

// ---- lib/src/strict/curried.dart ----
/// Dart-idiomatic currying: the `.curried` / `.uncurried` extension getters.
///
/// FxTS's `curry` cannot be ported as a function — it relies on runtime arity
/// reflection and recursive conditional types, neither of which exists in
/// Dart. Instead, one extension per arity is declared under the same getter
/// name, and the compiler picks the right one from the function's *static*
/// type. Full design rationale: `WHY_CURRIED.md` at the repository root.
///
/// ```dart
/// int add(int a, int b) => a + b;
/// final addOne = add.curried(1); // int Function(int)
/// addOne(2); // 3
/// ```

/// Curries a binary function: `f.curried(a)(b) == f(a, b)`.
///
/// Dart-native replacement for FxTS `curry` (see `WHY_CURRIED.md`).
extension Curry2<A, B, R> on R Function(A, B) {
  /// The curried form: `f.curried(a)(b) == f(a, b)`.
  R Function(B) Function(A) get curried => (a) => (b) => this(a, b);
}

/// Curries a ternary function: `f.curried(a)(b)(c) == f(a, b, c)`.
extension Curry3<A, B, C, R> on R Function(A, B, C) {
  /// The curried form: `f.curried(a)(b)(c) == f(a, b, c)`.
  R Function(C) Function(B) Function(A) get curried =>
      (a) => (b) => (c) => this(a, b, c);
}

/// Curries a 4-ary function.
extension Curry4<A, B, C, D, R> on R Function(A, B, C, D) {
  /// The curried form: `f.curried(a)(b)(c)(d) == f(a, b, c, d)`.
  R Function(D) Function(C) Function(B) Function(A) get curried =>
      (a) => (b) => (c) => (d) => this(a, b, c, d);
}

/// Curries a 5-ary function.
extension Curry5<A, B, C, D, E, R> on R Function(A, B, C, D, E) {
  /// The curried form: `f.curried(a)(b)(c)(d)(e) == f(a, b, c, d, e)`.
  R Function(E) Function(D) Function(C) Function(B) Function(A) get curried =>
      (a) => (b) => (c) => (d) => (e) => this(a, b, c, d, e);
}

/// Uncurries a 2-level function chain: `f.uncurried(a, b) == f(a)(b)`.
///
/// When the chain is nested deeper, the *deepest* matching arity wins; apply
/// an extension explicitly (`Uncurry2(f).uncurried`) to flatten fewer levels.
extension Uncurry2<A, B, R> on R Function(B) Function(A) {
  /// The flattened form: `f.uncurried(a, b) == f(a)(b)`.
  R Function(A, B) get uncurried => (a, b) => this(a)(b);
}

/// Uncurries a 3-level function chain.
extension Uncurry3<A, B, C, R> on R Function(C) Function(B) Function(A) {
  /// The flattened form: `f.uncurried(a, b, c) == f(a)(b)(c)`.
  R Function(A, B, C) get uncurried => (a, b, c) => this(a)(b)(c);
}

/// Uncurries a 4-level function chain.
extension Uncurry4<A, B, C, D, R>
    on R Function(D) Function(C) Function(B) Function(A) {
  /// The flattened form: `f.uncurried(a, b, c, d) == f(a)(b)(c)(d)`.
  R Function(A, B, C, D) get uncurried => (a, b, c, d) => this(a)(b)(c)(d);
}

/// Uncurries a 5-level function chain.
extension Uncurry5<A, B, C, D, E, R>
    on R Function(E) Function(D) Function(C) Function(B) Function(A) {
  /// The flattened form: `f.uncurried(a, b, c, d, e) == f(a)(b)(c)(d)(e)`.
  R Function(A, B, C, D, E) get uncurried =>
      (a, b, c, d, e) => this(a)(b)(c)(d)(e);
}

